{
  "intent": "Assess speaking sample for Proficiency Test",
  "entities": [
    {
      "name": "learner",
      "type": "user"
    },
    {
      "name": "speaking sample",
      "type": "audio_submission"
    },
    {
      "name": "Proficiency Test",
      "type": "assessment"
    },
    {
      "name": "rubric",
      "type": "scoring_criteria",
